/* From Uiverse.io by G4b413l - Tags: checkbox */
.__UIV_SCOPE__ label {
  display: block;
  width: 20px;
  height: 20px;
  cursor: pointer;
}

.__UIV_SCOPE__ input[type='checkbox'] {
  position: absolute;
  transform: scale(0);
}

.__UIV_SCOPE__ input[type='checkbox']:checked ~ .checkbox {
  transform: rotate(45deg);
  width: 14px;
  margin-left: 5px;
  border-color: #24c78e;
  border-width: 5px;
  border-top-color: transparent;
  border-left-color: transparent;
  border-radius: 0;
}

.__UIV_SCOPE__ .checkbox {
  display: block;
  width: inherit;
  height: inherit;
  border: solid 3px #2a2a2ab7;
  border-radius: 6px;
  transition: all 0.375s;
}
